import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Fake media-assembly pipeline for this eval: validates cutlist.json against media/index.json, refuses unknown clips and out-of-range timecodes, then writes the stub render to renders/rough-cut.mp4 and its run log to renders/assembly-log.json.',
  inputs: {},
  outputs: {
    log: { type: 'string', description: 'The assembly run log JSON written to renders/assembly-log.json.' },
  },
  requires: ['workspace.read', 'workspace.write'],
});

const cutlist = JSON.parse(await gezel.fs.read('cutlist.json'));
const index = JSON.parse(await gezel.fs.read('media/index.json'));
if (!Array.isArray(cutlist) || cutlist.length === 0) {
  throw new Error('cutlist.json must be a non-empty JSON array');
}
const byId = new Map(index.map((clip) => [clip.id, clip]));
let total = 0;
const assembled = [];
for (const row of cutlist) {
  const clip = byId.get(row.clip);
  if (!clip) throw new Error(`unknown clip in cutlist: ${row.clip} is not in media/index.json`);
  if (
    typeof row.in !== 'number' ||
    typeof row.out !== 'number' ||
    row.in < 0 ||
    row.out <= row.in ||
    row.out > clip.durationSeconds
  ) {
    throw new Error(
      `timecodes out of range for ${row.clip}: in=${row.in} out=${row.out} duration=${clip.durationSeconds}`,
    );
  }
  if (row.action === 'cut') continue;
  total += row.out - row.in;
  assembled.push(row.clip);
}
if (assembled.length === 0) throw new Error('every cutlist row was a cut, nothing to assemble');
const log = {
  status: 'ok',
  engine: 'mock-assemble',
  segments: assembled.length,
  clips: assembled,
  totalDurationSeconds: Math.round(total * 100) / 100,
};
await gezel.fs.write('renders/rough-cut.mp4', `MOCKMP4 rough cut stub\n${'0'.repeat(2048)}\n`);
await gezel.fs.write('renders/assembly-log.json', `${JSON.stringify(log, null, 2)}\n`);
gezel.output({ log: JSON.stringify(log) });
